definition.script:
pipeline {
  agent any
  stages {
    stage('Parallel checks') {
      parallel {
        stage('Lint') { steps { echo 'linting...'; sh 'sleep 1' } }
        stage('Unit') { steps { echo 'unit tests...'; sh 'sleep 2' } }
        stage('Dependency scan') { steps { echo 'scanning deps...'; sh 'sleep 1' } }
      }
    }
    stage('Build matrix') {
      matrix {
        axes {
          axis { name 'PLATFORM'; values 'linux', 'windows' }
          axis { name 'ARCH'; values 'amd64', 'arm64' }
        }
        stages {
          stage('Compile') {
            steps { echo "Building ${env.PLATFORM}/${env.ARCH}" }
          }
        }
      }
    }
  }
}
